#include <vector>
#include <limits>

class Node {
public:
    float g_value = 0.0;
    float h_value = std::numeric_limits<float>::max();
};

Node* find_next_node(std::vector<Node*>& open_list) {
    if (open_list.empty()) {
        return nullptr;
    }

    // Find node with lowest f-value (g_value + h_value)
    auto it = open_list.begin();
    Node* best_node = *it;
    float best_f = best_node->g_value + best_node->h_value;

    for (auto iter = open_list.begin() + 1; iter != open_list.end(); ++iter) {
        float current_f = (*iter)->g_value + (*iter)->h_value;
        if (current_f < best_f) {
            best_f = current_f;
            best_node = *iter;
            it = iter;
        }
    }

    // Remove the node from open_list
    std::iter_swap(it, open_list.end() - 1);
    open_list.pop_back();

    return best_node;
}

